package com.adria.transaction.client;import org.springframework.cloud.openfeign.FeignClient;import org.springframework.web.bind.annotation.*;import java.util.*;import java.math.*;@FeignClient(name="account-service") public interface AccountClient{@GetMapping("/api/accounts/{id}") Map<String,Object> getAccount(@PathVariable("id") UUID id);@PutMapping("/api/accounts/{id}/balance") Map<String,Object> updateBalance(@PathVariable("id") UUID id,@RequestParam("value") BigDecimal value);}